Rules.InvariantScript:
Refresh(tbl_contatos_entidades);
Refresh(tbl_contatos_entidades_log);

ClearCollect(
    col_gerenciarContatos,
    Sort(
        Filter(
            tbl_contatos_entidades,
            (
                IsBlank(cmbCKREAbloco_3.Selected.Value) ||
                Bloco = cmbCKREAbloco_3.Selected.Value
            ) &&
            (
                IsBlank(cmbCKREAaeroporto_3.Selected.Value) ||
                Aeroporto = cmbCKREAaeroporto_3.Selected.Value
            )
        ),
        status,
        SortOrder.Ascending
    )
)

ControlPropertyState.AutoRuleBindingString:
With(
    {
        baseREA: Filter(
            Sort(
                tbl_Checklist_REA_base,
                ID,
                SortOrder.Descending
            ),
            ID_modulo = var_idModulo && (varPerfilUser <> "Base" || Aeroporto = cmbCKREAaeroporto.Selected.Result)
        )
    },
    ClearCollect(
        col_checkListREA,
        Sort(
            baseREA,
            ID,
