);

Rules.InvariantScript:
With(
    {
        _contato: ThisItem,
        _idContato: ThisItem.ID
    },

    Set(
        varContatoHistorico,
        _contato
    );

    Refresh(tbl_contatos_entidades_log);

    ClearCollect(
        colHistoricoContato,
        Sort(
            Filter(
                tbl_contatos_entidades_log,
                id_contato = _idContato
            ),
            Criado,
            SortOrder.Descending
        )
    );

    UpdateContext(
        {
            var_visibleHistoricoContato: true
        }
    )
)

ControlPropertyState.AutoRuleBindingString:
Set(varContatoAntes, ThisItem);
Set(varContatoHistorico, ThisItem);

ClearCollect(
    colHistoricoContato,
    Sort(
        Filter(
            tbl_contatos_entidades_log,
            id_contato = ThisItem.ID
        ),
        Criado,
        SortOrder.Descending
    )
);

UpdateContext(
    {
        var_visibleFormContatos: true,
        var_acaoFormContatos: "Editar contato",
        var_dadosContatos: ThisItem
    }
);

EditForm(FormCadastrarContato)

Rules.InvariantScript:
With(
    {
        _idContato: ThisItem.ID
    },

    Refresh(tbl_contatos_entidades);

    Set(
        varContatoAntes,
        LookUp(
            tbl_contatos_entidades,
            ID = _idContato
        )
    );

    Set(
        varContatoHistorico,
        varContatoAntes
    );

    Set(
        varErroLogContato,
        ""
    );

    Set(
        varLogContatoCriado,
        LookUp(
            tbl_contatos_entidades_log,
            ID = -1
        )
    );

    Set(
        varSalvandoContato,
        false
    );

    Clear(colHistoricoContato);
    Clear(colAlteracoesContato);

    UpdateContext(
        {
            var_visibleFormContatos: true,
            var_acaoFormContatos: "Editar contato",
            var_dadosContatos: varContatoAntes
        }
    );

    ResetForm(FormCadastrarContato);
    EditForm(FormCadastrarContato)
)

ControlPropertyState.AutoRuleBindingString:
UpdateContext(
    {
        var_visibleFormContatos: true,
        var_acaoFormContatos: "Editar contato",
        var_dadosContatos: ThisItem
    }
);
EditForm(FormCadastrarContato)

Rules.InvariantScript:
Patch(
    tbl_contatos_entidades_log,
    Defaults(tbl_contatos_entidades_log),
    {
        id_contato: var_dadosContatos.ID,
        aeroporto: var_dadosContatos.Aeroporto,
        bloco: var_dadosContatos.Bloco,
        acao: "Exclusão",
        origem: "Gestão de Contatos",
        nome_contato: var_dadosContatos.nome,
        status_anterior: var_dadosContatos.status,
        status_novo: "Excluído",
        usuario_nome: User().FullName,
        usuario_email: User().Email,
        detalhes: "Contato excluído pela gestão de contatos.",
        DetalhesHtml:
            "<div style='font-family:Segoe UI, Arial, sans-serif; font-size:12px; color:#b42318;'>
                Contato excluído pela gestão de contatos.
            </div>"
    }
);

RemoveIf(
    tbl_contatos_entidades,
    ID = var_dadosContatos.ID
);

UpdateContext(
    {
        var_visibleExcluirContato: false,
        var_dadosContatos: Blank()
    }
);

Notify(
    "Contato excluído com registro de histórico.",
    NotificationType.Warning,
    4000
);

Select(ButtonRefreshChekREAcontatos_2)

With(
    {
        contatoDepois: FormCadastrarContato.LastSubmit,
        contatoAntes: varContatoAntes,
        acaoLog: If(
            IsBlank(varContatoAntes.ID),
            "Cadastro",
            "Atualização"
        )
    },

    Set(
        varErroLogContato,
        ""
    );

    ClearCollect(
        colAlteracoesContato,
        Filter(
            Table(
                {
                    Campo: "Aeroporto",
                    Antes: Coalesce(
                        contatoAntes.Aeroporto,
                        ""
                    ),
                    Depois: Coalesce(
                        contatoDepois.Aeroporto,
                        ""
                    )
                },
                {
                    Campo: "Bloco",
                    Antes: Coalesce(
                        contatoAntes.Bloco,
                        ""
                    ),
                    Depois: Coalesce(
                        contatoDepois.Bloco,
                        ""
                    )
                },
                {
                    Campo: "Tipificação",
                    Antes: Coalesce(
                        contatoAntes.tipo_entidade.Value,
                        ""
                    ),
                    Depois: Coalesce(
                        contatoDepois.tipo_entidade.Value,
                        ""
                    )
                },
                {
                    Campo: "Órgão/Entidade",
                    Antes: Coalesce(
                        contatoAntes.nome_orgao,
                        ""
                    ),
                    Depois: Coalesce(
                        contatoDepois.nome_orgao,
                        ""
                    )
                },
                {
                    Campo: "Nome",
                    Antes: Coalesce(
                        contatoAntes.nome,
                        ""
                    ),
                    Depois: Coalesce(
                        contatoDepois.nome,
                        ""
                    )
                },
                {
                    Campo: "Cargo/Função",
                    Antes: Coalesce(
                        contatoAntes.cargo,
                        ""
                    ),
                    Depois: Coalesce(
                        contatoDepois.cargo,
                        ""
                    )
                },
                {
                    Campo: "Cargo Motiva",
                    Antes: Coalesce(
                        contatoAntes.cargo_motiva.Value,
                        ""
                    ),
                    Depois: Coalesce(
                        contatoDepois.cargo_motiva.Value,
                        ""
                    )
                },
                {
                    Campo: "E-mail",
                    Antes: Coalesce(
                        contatoAntes.email,
                        ""
                    ),
                    Depois: Coalesce(
                        contatoDepois.email,
                        ""
                    )
                },
                {
                    Campo: "Colaborador Motiva",
                    Antes: Coalesce(
                        contatoAntes.email_ccr.DisplayName,
                        ""
                    ),
                    Depois: Coalesce(
                        contatoDepois.email_ccr.DisplayName,
                        ""
                    )
                },
                {
                    Campo: "E-mail Motiva",
                    Antes: Coalesce(
                        contatoAntes.email_ccr.Email,
                        ""
                    ),
                    Depois: Coalesce(
                        contatoDepois.email_ccr.Email,
                        ""
                    )
                },
                {
                    Campo: "Telefone principal",
                    Antes: Coalesce(
                        contatoAntes.tel_principal,
                        ""
                    ),
                    Depois: Coalesce(
                        contatoDepois.tel_principal,
                        ""
                    )
                },
                {
                    Campo: "Telefone reserva",
                    Antes: Coalesce(
                        contatoAntes.tel_reserva,
                        ""
                    ),
                    Depois: Coalesce(
                        contatoDepois.tel_reserva,
                        ""
                    )
                },
                {
                    Campo: "Capacidade",
                    Antes: Coalesce(
                        contatoAntes.capacidade,
                        ""
                    ),
                    Depois: Coalesce(
                        contatoDepois.capacidade,
                        ""
                    )
                },
                {
                    Campo: "Distância",
                    Antes: Coalesce(
                        contatoAntes.distancia,
                        ""
                    ),
                    Depois: Coalesce(
                        contatoDepois.distancia,
                        ""
                    )
                },
                {
                    Campo: "Tempo estimado de deslocamento",
                    Antes: Coalesce(
                        contatoAntes.tempo_estimado_de_deslocamento,
                        ""
                    ),
                    Depois: Coalesce(
                        contatoDepois.tempo_estimado_de_deslocamento,
                        ""
                    )
                },
                {
                    Campo: "Status",
                    Antes: Coalesce(
                        contatoAntes.status,
                        ""
                    ),
                    Depois: Coalesce(
                        contatoDepois.status,
                        ""
                    )
                }
            ),
            acaoLog = "Cadastro" ||
            Antes <> Depois
        )
    );

    IfError(
        With(
            {
                _logCriado:
                    Patch(
                        tbl_contatos_entidades_log,
                        Defaults(tbl_contatos_entidades_log),
                        {
                            id_contato: contatoDepois.ID,
                            aeroporto: contatoDepois.Aeroporto,
                            bloco: contatoDepois.Bloco,
                            acao: acaoLog,
                            origem: "Gestão de Contatos",
                            nome_contato: contatoDepois.nome,

                            status_anterior: If(
                                acaoLog = "Cadastro",
                                Blank(),
                                contatoAntes.status
                            ),

                            status_novo: contatoDepois.status,
                            usuario_nome: User().FullName,
                            usuario_email: User().Email,

                            detalhes:
                                Concat(
                                    colAlteracoesContato As ALT,
                                    ALT.Campo &
                                    ": " &
                                    Coalesce(
                                        ALT.Antes,
                                        ""
                                    ) &
                                    " → " &
                                    Coalesce(
                                        ALT.Depois,
                                        ""
                                    ),
                                    Char(10)
                                ),

                            DetalhesHtml:
                                "<table style='width:100%; border-collapse:collapse; font-family:Segoe UI,Arial,sans-serif; font-size:12px;'>" &

                                    "<thead>" &
                                        "<tr style='background:#111827; color:#ffffff; text-align:left;'>" &

                                            "<th style='padding:6px; border:1px solid #374151; width:28%;'>" &
                                                "Campo" &
                                            "</th>" &

                                            "<th style='padding:6px; border:1px solid #374151; width:36%;'>" &
                                                "Antes" &
                                            "</th>" &

                                            "<th style='padding:6px; border:1px solid #374151; width:36%;'>" &
                                                "Depois" &
                                            "</th>" &

                                        "</tr>" &
                                    "</thead>" &

                                    "<tbody>" &

                                        Concat(
                                            colAlteracoesContato As ALT,

                                            "<tr>" &

                                                "<td style='padding:6px; border:1px solid #d1d5db; font-weight:600; vertical-align:top;'>" &
                                                    ALT.Campo &
                                                "</td>" &

                                                "<td style='padding:6px; border:1px solid #d1d5db; color:#6b7280; vertical-align:top;'>" &
                                                    Coalesce(
                                                        ALT.Antes,
                                                        ""
                                                    ) &
                                                "</td>" &

                                                "<td style='padding:6px; border:1px solid #d1d5db; color:#111827; vertical-align:top;'>" &
                                                    Coalesce(
                                                        ALT.Depois,
                                                        ""
                                                    ) &
                                                "</td>" &

                                            "</tr>"
                                        ) &

                                    "</tbody>" &
                                "</table>"
                        }
                    )
            },

            Collect(
                colHistoricoContato,
                _logCriado
            );

            true
        ),

        Set(
            varErroLogContato,
            Coalesce(
                FirstError.Message,
                "Não foi possível registrar o histórico da atualização."
            )
        );

        false
    );

    Set(
        varContatoHistorico,
        contatoDepois
    );

    Refresh(tbl_contatos_entidades);
    Refresh(tbl_contatos_entidades_log);

    UpdateContext(
        {
            var_visibleFormContatos: false,
            var_dadosContatos: Blank()
        }
    );

    ResetForm(FormCadastrarContato);

    Set(
        varSalvandoContato,
        false
    );

    Select(ButtonRefreshChekREAcontatos_2);

    If(
        IsBlank(varErroLogContato),

        Notify(
            If(
                acaoLog = "Cadastro",
                "Contato cadastrado e histórico registrado com sucesso.",
                "Contato atualizado e histórico registrado com sucesso."
            ),
            NotificationType.Success,
            5000
        ),

        Notify(
            "O contato foi salvo, mas não foi possível registrar o histórico. " &
            "Detalhes: " &
            varErroLogContato,
            NotificationType.Error,
            8000
        )
    )
)

UpdateContext(
    {
        var_visibleHistoricoContato: false
    }
);

Set(varContatoHistorico, Blank());
Clear(colHistoricoContato)

With(
    {
        _busca: Lower(
            Trim(
                txtBuscarPlemPrai_2.Text
            )
        ),
        _aeroporto: cmbCKREAaeroporto_3.Selected.Value,
        _tipoContato: cmbContatosTipo.Selected.Value,
        _iata: Coalesce(
            LookUp(
                colAeros,
                Aeroporto = cmbCKREAaeroporto_3.Selected.Value,
                IATA
            ),
            "---"
        ),
        _revisao: Switch(
            cmbCKREAaeroporto_3.Selected.Value,

            // Uma linha por aeroporto — o texto à esquerda precisa ser IDÊNTICO ao valor do combo cmbCKREAaeroporto_3.
            "URUGUAIANA", "Rev.04",
            "Nome do Aeroporto 2", "Rev.01",

            // Valor padrão: usado em "Todos os aeroportos" ou aeroporto ainda sem revisão definida acima.
            "Rev.02"
        )
    },

    With(
        {
            _dadosRelatorio:
                SortByColumns(
                    AddColumns(
                        Filter(
                            col_gerenciarContatos,

                            (
                                IsBlank(_aeroporto) ||
                                Aeroporto = _aeroporto
                            ) &&

                            (
                                IsBlank(_tipoContato) ||
                                tipo_entidade.Value = _tipoContato
                            ) &&

                            (
                                IsBlank(_busca) ||
                                _busca in Lower(
                                    Coalesce(
                                        Bloco,
                                        ""
                                    )
                                ) ||
                                _busca in Lower(
                                    Coalesce(
                                        Aeroporto,
                                        ""
                                    )
                                ) ||
                                _busca in Lower(
                                    Coalesce(
                                        nome,
                                        ""
                                    )
                                ) ||
                                _busca in Lower(
                                    Coalesce(
                                        nome_orgao,
                                        ""
                                    )
                                ) ||
                                _busca in Lower(
                                    Coalesce(
                                        cargo,
                                        ""
                                    )
                                ) ||
                                _busca in Lower(
                                    Coalesce(
                                        email,
                                        ""
                                    )
                                ) ||
                                _busca in Lower(
                                    Coalesce(
                                        tel_principal,
                                        ""
                                    )
                                ) ||
                                _busca in Lower(
                                    Coalesce(
                                        tel_reserva,
                                        ""
                                    )
                                ) ||
                                _busca in Lower(
                                    Text(ID)
                                )
                            )
                        ),

                        ordemStatus,

                        Switch(
                            status,
                            "Desatualizado",
                            1,
                            "Atualizado",
                            2,
                            3
                        )
                    ),

                    "ordemStatus",
                    SortOrder.Ascending,

                    "nome_orgao",
                    SortOrder.Ascending,

                    "nome",
                    SortOrder.Ascending
                )
        },

        With(
            {
                _totalContatos: CountRows(_dadosRelatorio),

                _totalAtualizados:
                    CountIf(
                        _dadosRelatorio,
                        status = "Atualizado"
                    ),

                _totalDesatualizados:
                    CountIf(
                        _dadosRelatorio,
                        status = "Desatualizado"
                    )
            },

            "<div style='
                width:100%;
                box-sizing:border-box;
                font-family:Segoe UI,Arial,sans-serif;
                color:#163245;
                background:#ffffff;
            '>" &

                "<table style='
                    width:100%;
                    border-collapse:collapse;
                    font-family:Segoe UI,Arial,sans-serif;
                    margin-bottom:10px;
                '>" &

                    "<tr>" &

                        "<td style='
                            width:33%;
                            vertical-align:middle;
                            padding:12px 8px;
                        '>" &

                            "<div style='
                                font-family:Segoe UI Rounded,Arial Rounded MT Bold,Segoe UI,Arial,sans-serif;
                                font-size:22px;
                                line-height:22px;
                                font-weight:800;
                                color:#1F438A;
                            '>" &
                                "ASUR" &
                            "</div>" &

                            "<div style='
                                margin-top:5px;
                                font-size:12px;
                                font-weight:600;
                                color:#1F438A;
                            '>" &

                                Coalesce(
                                    _aeroporto,
                                    "Todos os aeroportos"
                                ) &

                            "</div>" &

                        "</td>" &

                        "<td style='
                            width:34%;
                            vertical-align:middle;
                            text-align:center;
                            padding:12px 8px;
                        '>" &

                            "<div style='
                                font-size:11px;
                                font-weight:700;
                                color:#344054;
                            '>" &

                                "FOR-LO-" &
                                _iata &
                                "-SREA-001" &

                            "</div>" &

                        "</td>" &

                        "<td style='
                            width:33%;
                            vertical-align:middle;
                            text-align:right;
                            padding:12px 8px;
                            font-size:11px;
                            color:#526E7D;
                        '>" &

                            "<strong>" & _revisao & "</strong><br>" &
                            Text(
                                Today(),
                                "dd/mm/yyyy"
                            ) &

                        "</td>" &

                    "</tr>" &

                    "<tr>" &

                        "<td colspan='3' style='
                            padding:9px;
                            border:1px solid #C3D5DC;
                            background:#EAF1F4;
                            text-align:center;
                            font-size:15px;
                            font-weight:700;
                            color:#163245;
                        '>" &

                            "Lista de Contatos de Emergência" &

                        "</td>" &

                    "</tr>" &

                "</table>" &

                If(
                    _totalDesatualizados > 0,

                    "<div style='
                        margin:10px 0;
                        padding:11px 13px;
                        border:1px solid #C3D5DC;
                        border-left:5px solid #C92050;
                        border-radius:7px;
                        background:#FCE9EF;
                        color:#C92050;
                    '>" &

                        "<div style='
                            font-size:13px;
                            font-weight:700;
                            margin-bottom:3px;
                        '>" &

                            "Atenção: existem contatos desatualizados" &

                        "</div>" &

                        "<div style='font-size:11px;'>" &

                            Text(_totalDesatualizados) &

                            If(
                                _totalDesatualizados = 1,
                                " contato requer validação e atualização cadastral.",
                                " contatos requerem validação e atualização cadastral."
                            ) &

                        "</div>" &

                    "</div>",

                    "<div style='
                        margin:10px 0;
                        padding:10px 13px;
                        border:1px solid #C3D5DC;
                        border-left:5px solid #157449;
                        border-radius:7px;
                        background:#E6F3EC;
                        color:#157449;
                        font-size:12px;
                        font-weight:600;
                    '>" &

                        "Todos os contatos apresentados estão atualizados." &

                    "</div>"
                ) &

                "<table style='
                    width:100%;
                    border-collapse:separate;
                    border-spacing:6px 0;
                    margin:10px 0 14px 0;
                    font-family:Segoe UI,Arial,sans-serif;
                '>" &

                    "<tr>" &

                        "<td style='
                            width:33.33%;
                            padding:10px;
                            border:1px solid #C3D5DC;
                            border-radius:7px;
                            background:#F7FAFB;
                            text-align:center;
                        '>" &

                            "<div style='
                                font-size:10px;
                                color:#6E8592;
                                text-transform:uppercase;
                                letter-spacing:0.4px;
                            '>" &
                                "Total de contatos" &
                            "</div>" &

                            "<div style='
